// Per-race highlights for the home page. Generated by scripts/highlights/race_highlights.py
// (FastF1, official F1 timing) — never hand-edited. Each block carries its own `source`; a race
// without a file, or a file missing a block, hides that module instead of showing a stale number.
// Static imports (not fs) so this works on the Cloudflare Worker runtime too: add one line per race.
import r2026_17 from '@/content/race-highlights/2026-17.json';

export type PoleLap = {
  driver: string;
  lapTime: string;
  speedKmh: number[];
  topSpeedKmh: number;
  minSpeedKmh: number;
  source: string;
};

export type TrackMap = {
  width: number;
  height: number;
  points: [number, number, number][];
  topSpeedAt: [number, number];
  minSpeedAt: [number, number];
  source: string;
};

export type DuelDriver = {
  driver: string;
  lapTime: string;
  sectors: [number, number, number];
  teamColour: string | null;
};

export type PoleDuel = {
  pole: DuelDriver;
  challenger: DuelDriver;
  source: string;
};

export type LapsLed = {
  driver: string;
  laps: number;
  totalLaps: number;
  source: string;
};

export type RaceHighlights = {
  year: number;
  round: number;
  event: string;
  poleLap?: PoleLap;
  trackMap?: TrackMap;
  poleDuel?: PoleDuel;
  lapsLed?: LapsLed;
};

const REGISTRY: Record<string, RaceHighlights> = {
  '2026-17': r2026_17 as RaceHighlights,
};

export function getRaceHighlightsFor(year: number, round: number): RaceHighlights | null {
  return REGISTRY[`${year}-${round}`] ?? null;
}
